import{h as i,j as e,i as n,L as r}from"./index-IDntzBfm.js";import{P as a,a as t,b as s}from"./ProsePage-OOUqEkLz.js";function l(){return i(n.about),e.jsxs(a,{eyebrow:n.about.eyebrow,title:n.about.heading,standfirst:n.about.standfirst,updated:n.about.updated,children:[e.jsx(t,{children:"What Rebyuu is"}),e.jsx("p",{children:"Rebyuu is a way to find anime worth watching and keep track of what you have seen. It covers roughly 22,000 titles, filterable by genre, format, season, year and airing status, with live trending and currently-airing rankings on the homepage. Browsing, searching and reading are open to everyone. An account is needed only to rate a title, write a review, or save something to a collection."}),e.jsx(t,{children:"Where the data comes from"}),e.jsx("p",{children:"Almost none of the catalogue text is ours, and it would be misleading to present it as though it were."}),e.jsx(s,{children:"AniList"}),e.jsxs("p",{children:["Titles, synopses, genre tags, season and year, airing status, episode counts and artwork all come from"," ",e.jsx("a",{href:"https://anilist.co",rel:"noopener noreferrer",target:"_blank",className:"underline underline-offset-2 hover:text-orange",children:"AniList"}),", through its public GraphQL API. Synopsis text is reproduced with HTML stripped and otherwise unchanged. Where a synopsis carries its own source note — you will see things like ",e.jsx("em",{children:"(Source: Crunchyroll)"})," — that note is part of AniList's text and refers to AniList's upstream, not to us. Cover and banner images are served directly from AniList's servers rather than copied onto ours."]}),e.jsx(s,{children:"MyAnimeList, via Jikan"}),e.jsxs("p",{children:["The score in the homepage's featured banner comes from"," ",e.jsx("a",{href:"https://myanimelist.net",rel:"noopener noreferrer",target:"_blank",className:"underline underline-offset-2 hover:text-orange",children:"MyAnimeList"}),", read through"," ",e.jsx("a",{href:"https://jikan.moe",rel:"noopener noreferrer",target:"_blank",className:"underline underline-offset-2 hover:text-orange",children:"Jikan"}),", an unofficial community-maintained API. Jikan is not affiliated with MyAnimeList, and neither are we. When MyAnimeList has no score for the featured title, the banner shows AniList's instead and labels it as AniList's."]}),e.jsx(t,{children:"How to read the scores"}),e.jsx("p",{children:"A title page can show two different numbers, and they measure different things."}),e.jsxs("p",{children:["The ",e.jsx("strong",{children:"AniList score"})," is the average score AniList's users have given the title — their votes, not ours. We show it because it is genuinely useful, but it is their verdict, not Rebyuu's. For that reason we deliberately do not mark it up as this page's own rating in structured data: presenting another platform's aggregate as our own is exactly the kind of thing that makes review snippets untrustworthy across the whole web."]}),e.jsxs("p",{children:["The ",e.jsx("strong",{children:"Rebyuu community score"})," is ours: the mean of ratings left by Rebyuu accounts on that title. It appears only once a title has enough ratings to mean anything, and it says how many it is based on. Early on, most titles will not have one. An empty number is more honest than a fabricated one."]}),e.jsx(t,{children:"What is actually ours"}),e.jsx("p",{children:"The interface and its design, the discovery and filtering logic, the live-updated trending and airing rails, and every rating and review written by a Rebyuu account holder. Reviews belong to the people who wrote them."}),e.jsx(t,{children:"Editorial policy"}),e.jsx("p",{children:"We do not write synopses and we do not paraphrase other people's. If a title page has original writing on it, it will be visibly labelled as ours. We do not generate descriptions automatically to fill space — a page with nothing of its own to say shows the source material and stops there."}),e.jsx("p",{children:"Nothing on this site is paid placement. Rankings come from AniList's public popularity and trending data or from Rebyuu users' own ratings, and nobody can buy a position in them."}),e.jsx(t,{children:"Corrections and contact"}),e.jsxs("p",{children:["If something here is wrong, or you hold rights to something surfaced on this site and want it credited differently or removed, raise it on the"," ",e.jsx("a",{href:"https://github.com/utkarshthakur303/rebyuu",rel:"noopener noreferrer",target:"_blank",className:"underline underline-offset-2 hover:text-orange",children:"project repository"}),". Corrections to catalogue data itself are usually best made at AniList, since that is where it originates and where a fix will propagate from."]}),e.jsx(t,{children:"Related"}),e.jsxs("p",{children:[e.jsx(r,{to:"/privacy",className:"underline underline-offset-2 hover:text-orange",children:"Privacy Policy"})," · ",e.jsx(r,{to:"/terms",className:"underline underline-offset-2 hover:text-orange",children:"Terms of Service"})," · ",e.jsx(r,{to:"/browse",className:"underline underline-offset-2 hover:text-orange",children:"Browse the catalogue"})]})]})}export{l as default};
